fn main() {
    let mut args = std::env::args();
    let program = args.next().unwrap_or_else(|| "fruit-table".to_string());
    let csv = match args.next().as_deref() {
        None => false,
        Some("--csv") => true,
        Some(option) => {
            eprintln!("usage: {program} [--csv] (unexpected argument: {option})");
            std::process::exit(2);
        }
    };

    if args.next().is_some() {
        eprintln!("usage: {program} [--csv] (too many arguments)");
        std::process::exit(2);
    }

    if csv {
        println!("fruit,count");
        for (name, count) in TABLE {
            println!("{name},{count}");
        }
    } else {
        for (name, count) in TABLE {
            println!("{name:<8}{count}");
        }
    }
}
